import{_ as d,C as i,o as c,c as o,j as e,a as s,G as r,a3 as l}from"./chunks/framework.Bvm_liKL.js";const v=JSON.parse('{"title":"URL 命令调用","description":"","frontmatter":{},"headers":[],"relativePath":"cn/guide/url-commands.md","filePath":"cn/guide/url-commands.md"}'),n={name:"cn/guide/url-commands.md"};function h(p,t,b,u,g,m){const a=i("ArticleMetadata");return c(),o("div",null,[t[0]||(t[0]=e("h1",{id:"url-命令调用",tabindex:"-1"},[s("URL 命令调用 "),e("a",{class:"header-anchor",href:"#url-命令调用","aria-label":'Permalink to "URL 命令调用"'},"​")],-1)),r(a),t[1]||(t[1]=l(`<p>ICC-CE 支持通过 <code>icc://</code> 开头的网址来控制软件。您可以把常用操作做成桌面快捷方式，或者交给一体机的中控软件、班牌系统去调用。</p><p>比较典型的用法：</p><ul><li>上课前用一条命令切换到您习惯的配置方案</li><li>下课时一键清空墨迹并收纳工具栏</li><li>让中控面板上的实体按钮直接切换画笔和橡皮</li></ul><h2 id="先打开开关" tabindex="-1">先打开开关 <a class="header-anchor" href="#先打开开关" aria-label="Permalink to &quot;先打开开关&quot;">​</a></h2><p>这个功能<strong>默认是关闭的</strong>，需要先启用：</p><ol><li>打开设置 → <strong>启动</strong></li><li>找到「<strong>外部协议调用 (icc://)</strong>」，说明文字是「通过 icc:// 协议从外部控制软件」</li><li>把开关打开</li></ol><div class="warning custom-block"><p class="custom-block-title">没打开开关时命令会被忽略</p><p>软件不会弹任何提示，命令就是没反应。如果您试了半天没效果，先回来确认这个开关是开着的。</p></div><div class="warning custom-block"><p class="custom-block-title">移动过软件文件夹，要关掉开关再打开</p><p>ICC-CE 是绿色软件。如果您把整个文件夹移动、改名或换了盘，命令就会失效——但<strong>开关仍然显示为开启</strong>，界面上看不出任何异常。</p><p>原因是记录的启动位置还指向旧地址。解决办法很简单：把「外部协议调用」开关<strong>关掉，再重新打开</strong>，位置就更新了。</p><p>另外这个设置只对<strong>当前 Windows 账户</strong>生效。教室电脑如果有多个账户，每个账户都要各自打开一次。</p></div><h2 id="怎么用" tabindex="-1">怎么用 <a class="header-anchor" href="#怎么用" aria-label="Permalink to &quot;怎么用&quot;">​</a></h2><h3 id="直接运行" tabindex="-1">直接运行 <a class="header-anchor" href="#直接运行" aria-label="Permalink to &quot;直接运行&quot;">​</a></h3><p>按 <kbd>Win</kbd> + <kbd>R</kbd>，输入命令回车，比如：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>icc://fold</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>浏览器地址栏里输入也可以，会提示您确认打开 ICC-CE。</p><h3 id="做成桌面快捷方式" tabindex="-1">做成桌面快捷方式 <a class="header-anchor" href="#做成桌面快捷方式" aria-label="Permalink to &quot;做成桌面快捷方式&quot;">​</a></h3><ol><li>桌面右键 → 新建 → 快捷方式</li><li>位置填命令，例如 <code>icc://clear</code></li><li>起个名字，比如「清空墨迹」</li></ol><p>双击就能用。也可以右键快捷方式 → 属性 → 快捷键，给它配一个组合键。</p><h3 id="写成批处理" tabindex="-1">写成批处理 <a class="header-anchor" href="#写成批处理" aria-label="Permalink to &quot;写成批处理&quot;">​</a></h3><p>新建一个 <code>.bat</code> 文件，几条命令连起来：</p><div class="language-bat vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">start</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> icc://config-profile/switch?name=上课</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">timeout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /t </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">start</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> icc://unfold</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">连续命令之间留点时间</p><p>每条命令都会去唤起软件，连着发太快可能有的没被处理。像上面那样用 <code>timeout /t 1</code> 隔开一秒比较稳妥。</p></div><h3 id="给中控软件用" tabindex="-1">给中控软件用 <a class="header-anchor" href="#给中控软件用" aria-label="Permalink to &quot;给中控软件用&quot;">​</a></h3><p>大部分一体机的中控软件都支持&quot;执行自定义命令&quot;或&quot;打开链接&quot;，把 <code>icc://</code> 命令填进去就行。软件没启动时会自动启动，已经在运行就直接执行。</p><h2 id="命令地址一览" tabindex="-1">命令地址一览 <a class="header-anchor" href="#命令地址一览" aria-label="Permalink to &quot;命令地址一览&quot;">​</a></h2><h3 id="工具栏" tabindex="-1">工具栏 <a class="header-anchor" href="#工具栏" aria-label="Permalink to &quot;工具栏&quot;">​</a></h3><table tabindex="0"><thead><tr><th>地址</th><th>效果</th></tr></thead><tbody><tr><td><code>icc://fold</code></td><td>收纳工具栏</td></tr><tr><td><code>icc://unfold</code></td><td>展开工具栏</td></tr><tr><td><code>icc://toggle</code></td><td>收纳与展开来回切换</td></tr><tr><td><code>icc://thoroughhideon</code></td><td>开启「收纳时彻底隐藏」</td></tr><tr><td><code>icc://thoroughhideoff</code></td><td>关闭「收纳时彻底隐藏」</td></tr><tr><td><code>icc://thoroughhidetoggle</code></td><td>切换该选项</td></tr></tbody></table><p><code>thoroughhide</code> 这三条会<strong>改动并保存设置</strong>，跟您在设置里手动改是一样的效果。</p><h3 id="画笔与工具" tabindex="-1">画笔与工具 <a class="header-anchor" href="#画笔与工具" aria-label="Permalink to &quot;画笔与工具&quot;">​</a></h3><table tabindex="0"><thead><tr><th>地址</th><th>效果</th></tr></thead><tbody><tr><td><code>icc://tool/pen</code></td><td>切到画笔</td></tr><tr><td><code>icc://tool/cursor</code></td><td>切到光标（鼠标模式）</td></tr><tr><td><code>icc://tool/eraser</code></td><td>切到面积橡皮</td></tr><tr><td><code>icc://tool/eraserbystrokes</code></td><td>切到笔画橡皮</td></tr><tr><td><code>icc://tool/select</code></td><td>切到套索选择</td></tr></tbody></table><h3 id="墨迹" tabindex="-1">墨迹 <a class="header-anchor" href="#墨迹" aria-label="Permalink to &quot;墨迹&quot;">​</a></h3><table tabindex="0"><thead><tr><th>地址</th><th>效果</th></tr></thead><tbody><tr><td><code>icc://clear</code></td><td>清空当前墨迹</td></tr><tr><td><code>icc://clearall</code></td><td>清空墨迹，并且不能再撤销</td></tr><tr><td><code>icc://undo</code></td><td>撤销</td></tr><tr><td><code>icc://redo</code></td><td>重做</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">clearall 清掉的东西找不回来</p><p><code>icc://clear</code> 清空后还能用 <code>icc://undo</code> 撤销回来。<code>icc://clearall</code> 会连撤销记录一起清掉，<strong>没法恢复</strong>。做快捷方式时留意别弄混。</p></div><h3 id="白板翻页" tabindex="-1">白板翻页 <a class="header-anchor" href="#白板翻页" aria-label="Permalink to &quot;白板翻页&quot;">​</a></h3><table tabindex="0"><thead><tr><th>地址</th><th>效果</th></tr></thead><tbody><tr><td><code>icc://nextpage</code></td><td>下一页</td></tr><tr><td><code>icc://previouspage</code></td><td>上一页</td></tr><tr><td><code>icc://newpage</code></td><td>新建一页</td></tr><tr><td><code>icc://deletepage</code></td><td>删除当前页</td></tr></tbody></table><h3 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to &quot;功能&quot;">​</a></h3><table tabindex="0"><thead><tr><th>地址</th><th>效果</th></tr></thead><tbody><tr><td><code>icc://whiteboard</code></td><td>打开/关闭白板</td></tr><tr><td><code>icc://rand</code></td><td>随机点名</td></tr><tr><td><code>icc://randone</code></td><td>抽一个人</td></tr><tr><td><code>icc://timer</code></td><td>倒计时</td></tr><tr><td><code>icc://screenshot</code></td><td>截图并插入画布</td></tr></tbody></table><h3 id="配置方案" tabindex="-1">配置方案 <a class="header-anchor" href="#配置方案" aria-label="Permalink to &quot;配置方案&quot;">​</a></h3><p>如果您建了多个配置方案（比如「语文课」「数学课」），可以直接切换：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>icc://config-profile/switch?name=方案名</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">方案名要写得完全一致</p><p>大小写、空格都得跟您建的方案名一模一样，写错了不会有提示，只是不生效。名字里有空格或中文一般没问题，直接写就行。</p></div><h3 id="打开设置页" tabindex="-1">打开设置页 <a class="header-anchor" href="#打开设置页" aria-label="Permalink to &quot;打开设置页&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>icc://settings</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>也可以直接跳到某一页，例如打开画布设置：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>icc://settings/CanvasPage</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="重启与退出" tabindex="-1">重启与退出 <a class="header-anchor" href="#重启与退出" aria-label="Permalink to &quot;重启与退出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>地址</th><th>效果</th></tr></thead><tbody><tr><td><code>icc://restart</code></td><td>重启软件</td></tr><tr><td><code>icc://exit</code></td><td>退出软件</td></tr><tr><td><code>icc://restart/admin</code></td><td>以管理员身份重启</td></tr><tr><td><code>icc://restart/normal</code></td><td>以普通身份重启</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">这几条命令 3 秒内只执行一次</p><p>防止中控面板的按钮被连按导致反复重启。3 秒内重复的会被忽略，这是正常的。</p></div><h2 id="墨迹冻结" tabindex="-1">墨迹冻结 <a class="header-anchor" href="#墨迹冻结" aria-label="Permalink to &quot;墨迹冻结&quot;">​</a></h2><p>配合墨迹冻结功能使用：</p><table tabindex="0"><thead><tr><th>地址</th><th>效果</th></tr></thead><tbody><tr><td><code>icc://freeze</code></td><td>冻结当前页</td></tr><tr><td><code>icc://unfreeze</code></td><td>解冻当前页</td></tr><tr><td><code>icc://freeze/start</code></td><td>课程开始</td></tr><tr><td><code>icc://freeze/end</code></td><td>课程结束</td></tr><tr><td><code>icc://freeze/cancel</code></td><td>取消</td></tr></tbody></table><p>想指定某一页，加上 <code>?page=</code>（范围 0 到 100）：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>icc://freeze?page=3</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="danger custom-block"><p class="custom-block-title">用 URL 解冻会跳过密码</p><p>如果您给冻结的页面设了密码，<code>icc://unfreeze</code> <strong>不会要求输入密码</strong>就直接解冻。</p><p>这也是为什么「外部协议调用」默认关闭。如果您依赖冻结密码来防止学生改动内容，就不要打开这个开关，或者至少不要把解冻命令做成桌面上的快捷方式。</p></div><h2 id="命令没反应" tabindex="-1">命令没反应？ <a class="header-anchor" href="#命令没反应" aria-label="Permalink to &quot;命令没反应？&quot;">​</a></h2><p>按顺序检查：</p><ol><li><strong>开关是否打开</strong> — 设置 → 启动 → 外部协议调用 (icc://)，这是最常见的原因</li><li><strong>软件文件夹是否移动过</strong> — 移动后需要重新打开一次开关</li><li><strong>地址是否拼错</strong> — 命令不区分大小写，<code>icc://Fold</code> 和 <code>icc://fold</code> 都行，但拼错字就不认了</li><li><strong>配置方案名是否对得上</strong> — 方案名区分大小写，要完全一致</li><li><strong>是不是 3 秒内重复调用了重启/退出</strong> — 这是有意的限制</li></ol><p>都排除了还不行的话，可以到软件目录下的 <code>Logs</code> 文件夹里找最新的日志文件，搜索 <code>URI</code> 就能看到软件收到了什么命令、为什么没执行。反馈问题时附上这段日志会快很多。</p><h2 id="相关内容" tabindex="-1">相关内容 <a class="header-anchor" href="#相关内容" aria-label="Permalink to &quot;相关内容&quot;">​</a></h2><ul><li><a href="/website/cn/guide/files-and-data">配置文件与数据目录</a> — 配置方案存在哪</li><li><a href="/website/cn/guide/settings">设置指南</a> — 各项设置的说明</li><li><a href="/website/cn/guide/troubleshooting">故障排除</a> — 其他常见问题</li><li><a href="/website/cn/dev/core/uri">URI 协议调用</a> — 面向开发者的完整命令与实现细节</li></ul>`,58))])}const f=d(n,[["render",h]]);export{v as __pageData,f as default};
